hooks.command:
pwsh -NoProfile -Command @'
$claudeMdPath = Join-Path (Get-Location).Path 'CLAUDE.md'
$memoryPath = Join-Path (Get-Location).Path '.claude\projects\c--Projects-plugin\memory\MEMORY.md'

if (-not (Test-Path $memoryPath)) {
  $memoryPath = Join-Path (Get-Location).Path '.\memory\MEMORY.md'
}

if (Test-Path $memoryPath) {
  # Extract latest status from MEMORY.md
  $memory = Get-Content $memoryPath -Raw
  $statusMatch = $memory | Select-String -Pattern '## Latest Status \(UPDATED ([^)]+)' | Select-Object -First 1

  if ($statusMatch) {
    $timestamp = $statusMatch.Matches[0].Groups[1].Value
    # Update CLAUDE.md with status timestamp if needed
    $claudeMd = Get-Content $claudeMdPath -Raw -ErrorAction SilentlyContinue
    if ($claudeMd -and -not ($claudeMd -match "Last updated: $timestamp")) {
      $claudeMd = $claudeMd -replace 'Last updated: [^\n]*', "Last updated: $timestamp"
      if (-not ($claudeMd -match 'Last updated:')) {
        $claudeMd = $claudeMd.TrimEnd() + "`n
**Last updated:** $timestamp"
      }
      Set-Content -Path $claudeMdPath -Value $claudeMd -Encoding UTF8
    }
  }
}

Write-Output '{"systemMessage": "✓ CLAUDE.md synced with memory"}'
'@
